import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, mul, add, uniform, normalMap } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // SCENE SETUP
  // ============================================================================
  const group = new THREE.Group();
  group.userData.handlers = {};
  const timelines = [];

  // ============================================================================
  // MATERIAL SETUP WITH DISPLACEMENT
  // ============================================================================

  // Load textures (non-blocking; handle async)
  let colorTexture = null;
  let displacementTexture = null;

  const material = new MeshStandardNodeMaterial({
    color: 0xffffff,
    metalness: 0.45,
    roughness: 0.6,
    clearcoat: 0.15,
    side: THREE.DoubleSide,
  });

  // TSL displacement setup
  const displacementScale = uniform(0.08);
  const displacementNode = mul(
    mix(
      uv().y, // Base on V for vertical variation
      uv().x, // Mix with U for 2D effect
      0.5
    ),
    displacementScale
  );

  material.positionNode = add(
    THREE.PositionNode || material.positionNode,
    mul(displacementNode, vec3(0, 1, 0.3))
  );

  // Load color and displacement textures
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colorTexture = tex;
    material.color.setHex(0xffffff);
    material.map = tex;
    material.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    displacementTexture = tex;
    material.displacementMap = tex;
    material.displacementScale = 0.08;
    material.needsUpdate = true;
  });

  // ============================================================================
  // GEOMETRY: Tessellated plane for displacement
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(2.5, 1.56, 64, 64);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.receiveShadow = true;
  mesh.castShadow = true;
  group.add(mesh);

  // ============================================================================
  // LIGHTING: Key + rim accent
  // ============================================================================
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.1);
  keyLight.position.set(1.5, 1.2, 2.0);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 1024;
  keyLight.shadow.mapSize.height = 1024;
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.6);
  rimLight.position.set(-2.0, -0.5, 1.5);
  group.add(rimLight);

  // ============================================================================
  // INTERACTION: Hover & Click handlers
  // ============================================================================

  group.userData.handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(
      mesh.position,
      {
        y: 0.15,
        duration: 0.5,
        ease: 'power3.out',
      },
      0
    );
    tl.to(
      mesh.rotation,
      {
        x: 0.02,
        duration: 0.5,
        ease: 'power3.out',
      },
      0
    );
    timelines.push(tl);
  };

  group.userData.handlers.hoverEnd = () => {
    const tl = gsap.timeline();
    tl.to(
      mesh.position,
      {
        y: 0,
        duration: 0.7,
        ease: 'power4.out',
      },
      0
    );
    tl.to(
      mesh.rotation,
      {
        x: 0,
        duration: 0.7,
        ease: 'power4.out',
      },
      0
    );
    timelines.push(tl);
  };

  group.userData.handlers.click = () => {
    const tl = gsap.timeline();
    tl.to(
      mesh.scale,
      {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      },
      0
    );
    tl.to(
      mesh.scale,
      {
        x: 1.0,
        y: 1.0,
        duration: 0.6,
        ease: 'power4.out',
      },
      0.12
    );
    timelines.push(tl);

    // Emit navigation event
    ctx.emit('navigate', { to: 'hub-features.select' });
  };

  // ============================================================================
  // CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    if (colorTexture) colorTexture.dispose();
    if (displacementTexture) displacementTexture.dispose();
    keyLight.dispose();
    rimLight.dispose();
  };

  return group;
}
